public class JacksonAnnotationIntrospector_refineSerializationType_TriageGen2Test {

    private JacksonAnnotationIntrospector introspector;
    private MapperConfig<?> config;
    private TypeFactory typeFactory;
    private Annotated annotated;

    // Dummy classes for testing inheritance and relationships
    public static class Base {}
    public static class Derived extends Base {}
    public static class Unrelated {}

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
        config = mock(MapperConfig.class);
        typeFactory = TypeFactory.defaultInstance();
        annotated = mock(Annotated.class);
        when(config.getTypeFactory()).thenReturn(typeFactory);
        when(annotated.getName()).thenReturn("testAnnotated");
    }

    @Test
    public void testRefineSerializationType_NoAnnotation() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(String.class);
        // Mock _findAnnotation to return null
        JacksonAnnotationIntrospector spyIntrospector = spy(introspector);
        doReturn(null).when(spyIntrospector)._findAnnotation(any(), eq(JsonSerialize.class));

        JavaType result = spyIntrospector.refineSerializationType(config, annotated, baseType);
        assertEquals(baseType, result);
    }

    @Test
    public void testRefineSerializationType_ExactMatch() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(Base.class);
        JsonSerialize ann = mock(JsonSerialize.class);
        when(ann.as()).thenReturn(Base.class);

        JacksonAnnotationIntrospector spyIntrospector = spy(introspector);
        doReturn(ann).when(spyIntrospector)._findAnnotation(any(), eq(JsonSerialize.class));
        // Mock _classIfExplicit to return the class
        doReturn(Base.class).when(spyIntrospector)._classIfExplicit(ann);

        JavaType result = spyIntrospector.refineSerializationType(config, annotated, baseType);

        // type.hasRawClass(serClass) should be true, resulting in static typing
        assertTrue(result.isStatic());
    }

    @Test
    public void testRefineSerializationType_GeneralizedType() throws JsonMappingException {
        // Base is type, Derived is annotation (subtype of Base)
        // Wait, the logic is: if (serClass.isAssignableFrom(currRaw)) -> Generalized
        // Example: baseType is Derived, serClass is Base. Base.class.isAssignableFrom(Derived.class) is true.
        JavaType baseType = typeFactory.constructType(Derived.class);
        JsonSerialize ann = mock(JsonSerialize.class);
        when(ann.as()).thenReturn(Base.class);

        JacksonAnnotationIntrospector spyIntrospector = spy(introspector);
        doReturn(ann).when(spyIntrospector)._findAnnotation(any(), eq(JsonSerialize.class));
        doReturn(Base.class).when(spyIntrospector)._classIfExplicit(ann);

        JavaType result = spyIntrospector.refineSerializationType(config, annotated, baseType);
        assertEquals(Base.class, result.getRawClass());
    }

    @Test
    public void testRefineSerializationType_SpecializedType() throws JsonMappingException {
        // baseType is Base, serClass is Derived. currRaw.isAssignableFrom(serClass) is true.
        JavaType baseType = typeFactory.constructType(Base.class);
        JsonSerialize ann = mock(JsonSerialize.class);
        when(ann.as()).thenReturn(Derived.class);

        JacksonAnnotationIntrospector spyIntrospector = spy(introspector);
        doReturn(ann).when(spyIntrospector)._findAnnotation(any(), eq(JsonSerialize.class));
        doReturn(Derived.class).when(spyIntrospector)._classIfExplicit(ann);

        JavaType result = spyIntrospector.refineSerializationType(config, annotated, baseType);
        assertEquals(Derived.class, result.getRawClass());
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineSerializationType_UnrelatedTypes() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(Base.class);
        JsonSerialize ann = mock(JsonSerialize.class);
        when(ann.as()).thenReturn(Unrelated.class);

        JacksonAnnotationIntrospector spyIntrospector = spy(introspector);
        doReturn(ann).when(spyIntrospector)._findAnnotation(any(), eq(JsonSerialize.class));
        doReturn(Unrelated.class).when(spyIntrospector)._classIfExplicit(ann);

        spyIntrospector.refineSerializationType(config, annotated, baseType);
    }

